    if not text {
        return False;
    }
    lowered = text.lower();
    signals = [
        "kill myself",
        "end my life",
        "want to die",
        "suicide",
        "hurt myself",
        "self harm",
        "self-harm",
        "can't go on",
        "cannot go on",
        "ending it all",
        "no reason to live"
    ];
    for signal in signals {
        if signal in lowered {
            return True;
        }
    }
    return False;
}
"}

