def wr_parse_threshold(text: str) -> dict {
    m = re.search(
        r"\b(fever|temperature|pain|nausea)\b.*?(?:over|above|greater than|>)\s*(\d+(?:\.\d+)?)",
        text,
        re.IGNORECASE
    );
    if m is None {
        return {};
    }
    metric: str = str(m.group(1)).lower();
    if metric == "temperature" {
        metric = "fever";
    }
    return {
        "metric": metric,
        "anchor_key": wr_resolve_symptom(metric),
        "operator": ">",
        "threshold": float(m.group(2)),
        "raw": text
    };
}
"}

